/** Male and female faces, in the order the prototype uses them. */
type Gender = 'm' | 'w'

/** Known people and the face each one has in the prototype (VT_MOCKPH). */
const FACE_INDEX: Readonly<Record<string, [Gender, number]>> = {
  Rahul: ['m', 0],
  Vivek: ['m', 1],
  Chary: ['m', 2],
  'Bhavana P': ['w', 0],
  Bhavana: ['w', 0],
  'Bharath Reddy Panyala': ['m', 3],
  Arjun: ['m', 4],
  Raj: ['m', 5],
  Ganesh: ['m', 6],
  Sofia: ['w', 1],
  Peter: ['m', 7],
}

/** First names that read as female when a name is not in FACE_INDEX. */
const FEMALE_NAME = /a$|i$|sofia|anna|maria|emma|nora|ingrid|sara/i

const hash = (s: string): number => {
  let x = 0
  for (let i = 0; i < s.length; i++) x = (x * 31 + s.charCodeAt(i)) >>> 0
  return x
}

const svgUrl = (svg: string) => 'data:image/svg+xml;utf8,' + encodeURIComponent(svg)

/** Two-letter initials: "Bhavana P" → "BP". Only letters are kept. */
export const initials = (name: string): string =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .map(w => w[0])
    .join('')
    .replace(/[^A-Za-z]/g, '')
    .slice(0, 2)
    .toUpperCase()

/**
 * The face photo for a person, or null when there is no name. A known name
 * gets its own face; any other name gets one from its hash, as the prototype does.
 */
export const faceFor = (name: string): string | null => {
  if (!name) return null
  const first = name.split(/\s+/)[0]
  const [gender, index] = FACE_INDEX[name] ?? FACE_INDEX[first] ?? (FEMALE_NAME.test(first) ? ['w', hash(name)] : ['m', hash(name)])
  const list = gender === 'w' ? FACES_W : FACES_M
  return list[index % list.length]
}

const TILE_COLOURS = ['#4870E8', '#9F89E5', '#B98A2F', '#3F9079']

/** A generated logo tile with the name's initials, for companies without a logo. */
const tileLogo = (name: string): string => {
  const colour = TILE_COLOURS[hash(name) % TILE_COLOURS.length]
  return svgUrl(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80"><rect width="80" height="80" rx="18" fill="${colour}"/>` +
      `<circle cx="58" cy="22" r="10" fill="#fff" opacity="0.3"/>` +
      `<text x="40" y="52" text-anchor="middle" font-family="Inter,Arial,sans-serif" font-size="30" font-weight="800" fill="#fff">${initials(name)}</text></svg>`,
  )
}

/**
 * The logo for a company or project name: the company's own logo when there is
 * one, otherwise a tile with its initials. A project name matches its company
 * by first word ("Daco platform" → Daco), as the prototype does.
 */
export const logoFor = (name: string): string => {
  if (!name) return ''
  if (COMPANY_LOGOS[name]) return COMPANY_LOGOS[name]
  const first = name.split(/\s+/)[0]
  const match = Object.keys(COMPANY_LOGOS).find(k => k.split(/\s+/)[0] === first)
  return match ? COMPANY_LOGOS[match] : tileLogo(name)
}
